use std::fs;
use std::io::{self, BufRead};
use std::path::{Path, PathBuf};
use regex::Regex;
use walkdir::WalkDir;
use colored::*;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse arguments
    let mut keyword = String::new();
    let mut replacement = String::new();
    let mut paths = Vec::new();
    let mut use_regex = false;
    let mut no_interactive = false;
    let mut no_recursive = false;
    let mut no_color = false;
    let mut show_color = true;
    let mut show_file = true;
    let mut skip_vcs = true;
    let mut show_version = false;
    let mut show_help = false;
    let mut verbose = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" | "-V" => show_version = true,
            "--help" | "-h" => show_help = true,
            "--regex" | "-r" => use_regex = true,
            "--no-interactive" => no_interactive = true,
            "--no-recursive" => no_recursive = true,
            "--no-color" => no_color = true,
            "--no-file" => show_file = false,
            "--no-skip-vcs" => skip_vcs = false,
            "--verbose" => verbose = true,
            "--column" => {},
            "--row" => {},
            "--binary" => {},
            "--statistics" => {},
            "--skipped" => {},
            "--preserve-time" => {},
            "--no-symlink" => {},
            "--no-skip-gitignore" => {},
            "--no-fixed-order" => {},
            "--no-parent-ignore" => {},
            "--tbm" => {},
            "--sse" => {},
            "--key-from-file" => {},
            "--rep-from-file" => {},
            "--max-threads" => { i += 1; },
            "--size-per-thread" => { i += 1; },
            "--bin-check-bytes" => { i += 1; },
            "--mmap-bytes" => { i += 1; },
            arg if arg.starts_with("--") => {
                eprintln!("Unknown flag: {}", arg);
                std::process::exit(1);
            }
            arg if !arg.starts_with("-") && keyword.is_empty() => {
                keyword = arg.to_string();
            }
            arg if !arg.starts_with("-") && replacement.is_empty() => {
                replacement = arg.to_string();
            }
            arg => {
                paths.push(arg.to_string());
            }
        }
        i += 1;
    }

    show_color = !no_color;

    if show_version {
        println!("ambr 0.6.0");
        return;
    }

    if show_help || keyword.is_empty() || replacement.is_empty() {
        print_help();
        return;
    }

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    // Process each path
    let mut found_matches = false;
    for path_str in paths {
        let path = Path::new(&path_str);
        if path.is_file() {
            if process_file(&path, &keyword, &replacement, use_regex, no_interactive, show_color, show_file, verbose) {
                found_matches = true;
            }
        } else if path.is_dir() {
            if !no_recursive {
                for entry in WalkDir::new(path)
                    .into_iter()
                    .filter_map(|e| e.ok())
                    .filter(|e| e.path().is_file())
                {
                    if should_skip_file(entry.path(), skip_vcs) {
                        continue;
                    }
                    if process_file(entry.path(), &keyword, &replacement, use_regex, no_interactive, show_color, show_file, verbose) {
                        found_matches = true;
                    }
                }
            }
        }
    }

    if !found_matches {
        std::process::exit(1);
    }
}

fn should_skip_file(path: &Path, skip_vcs: bool) -> bool {
    if !skip_vcs {
        return false;
    }

    let path_str = path.to_string_lossy();
    if path_str.contains("/.git/") || path_str.contains("\\.git\\") {
        return true;
    }
    if path_str.contains("/.hg/") || path_str.contains("\\.hg\\") {
        return true;
    }
    if path_str.contains("/.svn/") || path_str.contains("\\.svn\\") {
        return true;
    }
    if path_str.contains("/.bzr/") || path_str.contains("\\.bzr\\") {
        return true;
    }

    false
}

fn process_file(
    path: &Path,
    keyword: &str,
    replacement: &str,
    use_regex: bool,
    no_interactive: bool,
    show_color: bool,
    show_file: bool,
    verbose: bool,
) -> bool {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return false,
    };

    let mut found = false;
    let mut new_content = content.clone();

    if use_regex {
        match Regex::new(keyword) {
            Ok(re) => {
                if re.is_match(&content) {
                    found = true;
                    new_content = re.replace_all(&content, replacement).to_string();
                }
            }
            Err(_) => return false,
        }
    } else {
        if content.contains(keyword) {
            found = true;
            new_content = content.replace(keyword, replacement);
        }
    }

    if !found {
        return false;
    }

    if show_file && show_color {
        println!("{}", path.display().to_string().cyan());
    } else if show_file {
        println!("{}", path.display());
    }

    if no_interactive {
        if let Err(_) = fs::write(path, &new_content) {
            return false;
        }
    } else {
        // Interactive mode
        let lines = content.lines().zip(new_content.lines());
        for (old, new) in lines {
            if old != new {
                println!("  {} -> {}", old.red(), new.green());
                print!("Replace? ( Yes[Y], No[N], All[A], Quit[Q] ): ");
                io::stdout().flush().unwrap();

                let stdin = io::stdin();
                let mut line = String::new();
                stdin.lock().read_line(&mut line).unwrap();

                match line.trim().to_lowercase().as_str() {
                    "y" | "yes" => {
                        let _ = fs::write(path, &new_content);
                        break;
                    }
                    "n" | "no" => {
                        continue;
                    }
                    "a" | "all" => {
                        let _ = fs::write(path, &new_content);
                        break;
                    }
                    "q" | "quit" => {
                        return false;
                    }
                    _ => {}
                }
            }
        }
    }

    true
}

fn print_help() {
    println!("ambr 0.6.0\n");
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...\n");
    println!("FLAGS:");
    println!("        --key-from-file        Use file contents of KEYWORD as keyword for search");
    println!("        --rep-from-file        Use file contents of REPLACEMENT as keyword for replacement");
    println!("        --verbose              Verbose message");
    println!("    -r, --regex                Enable regular expression search");
    println!("        --column               Enable column output");
    println!("        --row                  Enable row output");
    println!("        --binary               Enable binary file search");
    println!("        --statistics           Enable statistics output");
    println!("        --skipped              Enable skipped file output");
    println!("        --preserve-time        Enable timestamp preserve");
    println!("        --no-interactive       Disable interactive replace");
    println!("        --no-recursive         Disable recursive directory search");
    println!("        --no-symlink           Disable symbolic link follow");
    println!("        --no-color             Disable colored output");
    println!("        --no-file              Disable filename output");
    println!("        --no-skip-vcs          Disable vcs directory ( .hg/.git/.svn ) skip");
    println!("        --no-skip-gitignore    Disable .gitignore skip");
    println!("        --no-fixed-order       Disable output order guarantee");
    println!("        --no-parent-ignore     Disable .*ignore file search at parent directories");
    println!("        --tbm                  [Experimental] Enable TBM matcher");
    println!("        --sse                  [Experimental] Enable SSE 4.2");
    println!("    -h, --help                 Prints help information");
    println!("    -V, --version              Prints version information\n");
    println!("OPTIONS:");
    println!("        --max-threads <NUM>          Number of max threads [default: 20]");
    println!("        --size-per-thread <BYTES>    File size per one thread [default: 1048576]");
    println!("        --bin-check-bytes <BYTES>    Read size for checking binary [default: 256]");
    println!("        --mmap-bytes <BYTES>         [Experimental] Minimum size for using mmap [default: 1048576]\n");
    println!("ARGS:");
    println!("    <KEYWORD>        Keyword for search");
    println!("    <REPLACEMENT>    Keyword for replace");
    println!("    <PATHS>...       Search paths");
}
