                    "y" | "yes" => {
                        let _ = fs::write(path, &new_content);
                        break;
                    }
                    "n" | "no" => {
                        continue;
                    }
                    "a" | "all" => {
                        let _ = fs::write(path, &new_content);
                        break;
                    }
                    "q" | "quit" => {
                        return false;
                    }
                    _ => {}
                }
            }
        }
    }

    true
}

fn print_help() {
