                        }
                        "n" | "no" => {
                            continue;
                        }
                        "a" | "all" => {
                            let _ = fs::write(path, &new_content);
                            break;
                        }
                        "q" | "quit" => {
                            return false;
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    true
